insert into public.texts (id, title, author, content, theme, difficulty) values
('00000000-0000-0000-0000-000000000101', 'О языке', 'Учебный фрагмент', 'Язык хранит память народа. Язык помогает человеку мыслить точнее. Это богатство важно беречь каждый день.', 'Язык и культура', 'medium')
on conflict (id) do update set
  title = excluded.title,
  author = excluded.author,
  content = excluded.content,
  theme = excluded.theme,
  difficulty = excluded.difficulty;

insert into public.tasks (id, part, task_number, topic, difficulty, text_id, question, type, explanation) values
('00000000-0000-0000-0000-000000000201', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'easy', null, 'Пишется А на месте пропуска в словах:\n1. гр..моздкий;\n2. школьный в..хтёр;\n3. р..стительность;\n4. высокий к..блук;\n5. нак..лоть дров.', 'multiple', 'А пишется в словах: вахтёр, растительность, каблук. В словах «громоздкий» и «наколоть» пишется О.'),
('00000000-0000-0000-0000-000000000211', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'medium', null, 'Пишется А на месте пропуска в словах:\n1. з..ря;\n2. к..снуться;\n3. изл..гать;\n4. пл..вец;\n5. прик..саться.', 'multiple', 'А пишется в словах «заря», «излагать», «прикасаться». В словах «коснуться» и «пловец» пишется О.'),
('00000000-0000-0000-0000-000000000212', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'medium', null, 'Пишется А на месте пропуска в словах:\n1. р..внина;\n2. выр..щенный;\n3. заг..релый;\n4. тв..рить;\n5. прил..гательное.', 'multiple', 'А пишется в словах «равнина», «выращенный», «прилагательное». В словах «загорелый», «творить» пишется О.'),
('00000000-0000-0000-0000-000000000213', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'easy', null, 'Пишется А на месте пропуска в словах:\n1. к..рандаш;\n2. к..рабль;\n3. б..гаж;\n4. к..рзина;\n5. к..пуста.', 'multiple', 'Словарные слова с буквой А: карандаш, багаж, капуста. В словах «корабль», «корзина» пишется О.'),
('00000000-0000-0000-0000-000000000214', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'hard', null, 'Пишется А на месте пропуска в словах:\n1. прил..жить;\n2. пол..жение;\n3. к..сательная;\n4. соприк..сновение;\n5. р..стение.', 'multiple', 'А пишется в словах «касательная» и «растение». В словах «приложить», «положение», «соприкосновение» пишется О.'),
('00000000-0000-0000-0000-000000000215', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'medium', null, 'Пишется А на месте пропуска в словах:\n1. в..кзал;\n2. б..лкон;\n3. п..льто;\n4. с..лдат;\n5. ф..милия.', 'multiple', 'Словарные написания: вокзал, балкон, пальто, солдат, фамилия. А пишется в словах 2, 3, 5.'),
('00000000-0000-0000-0000-000000000216', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'medium', null, 'Пишется А на месте пропуска в словах:\n1. р..стение;\n2. выр..сли;\n3. отр..сль;\n4. подр..стать;\n5. зар..сли.', 'multiple', 'В корне -раст-/-ращ- пишется А перед СТ/Щ и в исключении «отрасль». В словах «выросли», «заросли» пишется О.'),
('00000000-0000-0000-0000-000000000217', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'hard', null, 'Пишется А на месте пропуска в словах:\n1. пром..кнуть под дождём;\n2. обм..кнуть кисть в краску;\n3. м..кать хлеб в молоко;\n4. непром..каемый плащ;\n5. вым..кнуть губкой воду.', 'multiple', 'В значении «погружать в жидкость» пишется МАК: обмакнуть, макать. В значении «пропускать/впитывать жидкость» — МОК.'),
('00000000-0000-0000-0000-000000000218', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'medium', null, 'Пишется А на месте пропуска в словах:\n1. предл..гать;\n2. сл..жение;\n3. изл..жить;\n4. пол..гать;\n5. прил..гательное.', 'multiple', 'В корне -лаг- пишется А перед Г: предлагать, полагать, прилагательное. Перед Ж пишется О: сложение, изложить.'),
('00000000-0000-0000-0000-000000000219', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'easy', null, 'Пишется А на месте пропуска в словах:\n1. т..релка;\n2. с..бака;\n3. м..лина;\n4. к..ньки;\n5. л..пата.', 'multiple', 'Словарные слова с А: тарелка, малина, лопата. В словах «собака», «коньки» пишется О.'),
('00000000-0000-0000-0000-000000000220', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'medium', null, 'Пишется А на месте пропуска в словах:\n1. к..сание;\n2. прик..снуться;\n3. к..сательная;\n4. к..сой взгляд;\n5. неприк..саемый.', 'multiple', 'В корне -кас-/-кос- А пишется, если после корня есть суффикс А: касание, касательная, неприкасаемый. В словах «прикоснуться», «косой» пишется О.'),
('00000000-0000-0000-0000-000000000221', 'A', 1, 'А1. Орфография: буквы А/О в корне', 'hard', null, 'Пишется А на месте пропуска в словах:\n1. ур..внение;\n2. ср..внить числа;\n3. р..внодушный;\n4. выр..внять край;\n5. пор..вняться.', 'multiple', 'В корнях -равн-/-ровн- буква А связана со значением «равный, одинаковый»: уравнение, сравнить, равнодушный. В значении «ровный, гладкий» пишется О: выровнять.'),
('00000000-0000-0000-0000-000000000202', 'A', 5, 'Пунктуация в сложном предложении', 'medium', null, 'Сколько запятых нужно поставить: Когда начался дождь ученики вернулись в класс и учитель продолжил объяснение темы.', 'short', 'Нужны запятые после придаточной части и между частями сложного предложения.'),
('00000000-0000-0000-0000-000000000203', 'B', 12, 'Средства связи предложений в тексте', 'hard', '00000000-0000-0000-0000-000000000101', 'Определите средство связи второго и третьего предложений текста.', 'short', 'Повтор ключевого слова связывает предложения по смыслу.')
on conflict (id) do update set
  part = excluded.part,
  task_number = excluded.task_number,
  topic = excluded.topic,
  difficulty = excluded.difficulty,
  text_id = excluded.text_id,
  question = excluded.question,
  type = excluded.type,
  explanation = excluded.explanation;

